package com.ncdex.instrument.security;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import java.nio.charset.StandardCharsets; import java.util.Date;
@Component public class JwtService { private final SecretKey key; private final long ttl; public JwtService(@Value("${app.jwt.secret}") String secret,@Value("${app.jwt.ttl-ms:3600000}") long ttl){ if(secret.getBytes(StandardCharsets.UTF_8).length<32) throw new IllegalArgumentException("JWT secret must contain at least 32 bytes"); this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.ttl=ttl;} public String generate(String username,String role){long now=System.currentTimeMillis();return Jwts.builder().subject(username).claim("role",role).issuedAt(new Date(now)).expiration(new Date(now+ttl)).signWith(key).compact();} public io.jsonwebtoken.Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
